class Solution {
public:
    int maxSumAfterOperation(vector<int>& nums) {
        long long plain = nums[0];
        long long changed = 1LL * nums[0] * nums[0];
        long long answer = changed;
        for (int i = 1; i < static_cast<int>(nums.size()); ++i) {
            long long x = nums[i];
            changed = max({changed + x, plain + x * x, x * x});
            plain = max(x, plain + x);
            answer = max(answer, changed);
        }
        return static_cast<int>(answer);
    }
};
